t e = {};            e.percent = p * 100;            option.onProgress(e);          },        });        if (ret.res.statusCode === 200) {          console.log("上传成功", ret);        } else {          option.onError("上传失败");        }      } catch (error) {        console.error(error);        option.onError("上传失败");      }      this.loading = false;    },  },};

